"""Provider smoke test, generated by Loopsmith.

Checks that each provider you have a key for can (1) answer a plain question and
(2) complete a tool-calling round trip, which is what every agent here depends on.

  pip install anthropic openai
  export OPENAI_API_KEY=... GEMINI_API_KEY=...     # whichever providers you use
  python smoke_test.py                              # tests every provider that has a key set
  python smoke_test.py openai gemini                # only these
  python smoke_test.py openai:gpt-4o ollama:llama3.1  # pick a model with provider:model

Exit code is 0 only if every tested provider passes.
"""
import json
import os
import sys

PROVIDERS = {
    "anthropic": {"label": "Anthropic (Claude)", "sdk": "anthropic", "base_url": None, "key_env": "ANTHROPIC_API_KEY", "model": "claude-sonnet-5-5", "proper": False, "local": False},
    "openai": {"label": "OpenAI", "sdk": "openai", "base_url": None, "key_env": "OPENAI_API_KEY", "model": "gpt-5", "proper": True, "local": False},
    "gemini": {"label": "Google Gemini", "sdk": "openai", "base_url": "https://generativelanguage.googleapis.com/v1beta/openai/", "key_env": "GEMINI_API_KEY", "model": "gemini-2.5-pro", "proper": False, "local": False},
    "groq": {"label": "Groq", "sdk": "openai", "base_url": "https://api.groq.com/openai/v1", "key_env": "GROQ_API_KEY", "model": "llama-3.3-70b-versatile", "proper": False, "local": False},
    "mistral": {"label": "Mistral", "sdk": "openai", "base_url": "https://api.mistral.ai/v1", "key_env": "MISTRAL_API_KEY", "model": "mistral-large-latest", "proper": False, "local": False},
    "deepseek": {"label": "DeepSeek", "sdk": "openai", "base_url": "https://api.deepseek.com", "key_env": "DEEPSEEK_API_KEY", "model": "deepseek-chat", "proper": False, "local": False},
    "xai": {"label": "xAI (Grok)", "sdk": "openai", "base_url": "https://api.x.ai/v1", "key_env": "XAI_API_KEY", "model": "grok-4", "proper": False, "local": False},
    "together": {"label": "Together AI", "sdk": "openai", "base_url": "https://api.together.xyz/v1", "key_env": "TOGETHER_API_KEY", "model": "meta-llama/Llama-3.3-70B-Instruct-Turbo", "proper": False, "local": False},
    "openrouter": {"label": "OpenRouter (any model)", "sdk": "openai", "base_url": "https://openrouter.ai/api/v1", "key_env": "OPENROUTER_API_KEY", "model": "openai/gpt-4o-mini", "proper": False, "local": False},
    "ollama": {"label": "Ollama (local)", "sdk": "openai", "base_url": "http://localhost:11434/v1", "key_env": "", "model": "llama3.1", "proper": False, "local": True},
    "lmstudio": {"label": "LM Studio (local)", "sdk": "openai", "base_url": "http://localhost:1234/v1", "key_env": "", "model": "local-model", "proper": False, "local": True},
    "custom": {"label": "Custom OpenAI-compatible", "sdk": "openai", "base_url": "http://localhost:8000/v1", "key_env": "API_KEY", "model": "my-model", "proper": False, "local": False},
}
DEFAULT_FIRST = "anthropic"  # the provider this agent was built for
ADD_TOOL = {
    "name": "add",
    "description": "Add two integers and return the sum.",
    "input_schema": {"type": "object", "properties": {"a": {"type": "integer"}, "b": {"type": "integer"}}, "required": ["a", "b"]},
}


def make_client(p, base_url=None):
    if p["sdk"] == "anthropic":
        from anthropic import Anthropic

        return Anthropic(max_retries=2, timeout=60)
    from openai import OpenAI

    return OpenAI(base_url=base_url or p["base_url"], api_key=os.environ.get(p["key_env"], "not-needed") if p["key_env"] else "not-needed", max_retries=2, timeout=60)


def call_anthropic(client, model, messages, tools):
    kwargs = {"tools": tools} if tools else {}
    resp = client.messages.create(model=model, max_tokens=300, messages=messages, **kwargs)
    messages.append({"role": "assistant", "content": resp.content})
    text = "".join(b.text for b in resp.content if b.type == "text")
    calls = [(b.id, b.name, b.input) for b in resp.content if b.type == "tool_use"]
    return text, calls


def results_anthropic(messages, calls, outputs):
    messages.append({"role": "user", "content": [{"type": "tool_result", "tool_use_id": i, "content": o} for (i, _n, _a), o in zip(calls, outputs)]})


def call_openai(client, p, model, messages, tools):
    kwargs = {}
    if tools:
        kwargs["tools"] = [{"type": "function", "function": {"name": t["name"], "description": t["description"], "parameters": t["input_schema"]}} for t in tools]
    token_arg = "max_completion_tokens" if p["proper"] else "max_tokens"
    resp = client.chat.completions.create(model=model, messages=messages, **{token_arg: 300}, **kwargs)
    msg = resp.choices[0].message
    calls = []
    for n, c in enumerate(msg.tool_calls or []):
        try:
            args = json.loads(c.function.arguments or "{}")
        except json.JSONDecodeError:
            args = {}
        calls.append((c.id or f"call_{n}", c.function.name, args))
    entry = {"role": "assistant", "content": msg.content or ""}
    if calls:
        entry["tool_calls"] = [{"id": i, "type": "function", "function": {"name": n, "arguments": json.dumps(a)}} for i, n, a in calls]
    messages.append(entry)
    return msg.content or "", calls


def results_openai(messages, calls, outputs):
    for (i, _n, _a), o in zip(calls, outputs):
        messages.append({"role": "tool", "tool_call_id": i, "content": o})


def ask(pid, p, model, client, prompt, tools):
    """Run a short loop. Returns (final_text, tool_calls_made)."""
    messages = [{"role": "user", "content": prompt}]
    if p["sdk"] == "openai":
        messages.insert(0, {"role": "system", "content": "You are concise. Use tools when asked."})
    made = 0
    for _ in range(4):
        if p["sdk"] == "anthropic":
            text, calls = call_anthropic(client, model, messages, tools)
        else:
            text, calls = call_openai(client, p, model, messages, tools)
        if not calls:
            return text, made
        outputs = []
        for _i, name, args in calls:
            made += 1
            outputs.append(str(int(args["a"]) + int(args["b"])) if name == "add" else "error: unknown tool")
        if p["sdk"] == "anthropic":
            results_anthropic(messages, calls, outputs)
        else:
            results_openai(messages, calls, outputs)
    return "", made


def test(pid, model=None):
    p = PROVIDERS[pid]
    model = model or p["model"]
    base_url = os.environ.get("SMOKE_BASE_URL") if pid == "custom" else None
    client = make_client(p, base_url)
    problems = []
    text, _ = ask(pid, p, model, client, "Reply with the single word: pong", None)
    if "pong" not in text.lower():
        problems.append(f"plain reply was {text[:60]!r}")
    text, made = ask(pid, p, model, client, "Use the add tool to add 17 and 25, then tell me the sum.", [ADD_TOOL])
    if made == 0:
        problems.append("the model never called the tool")
    elif "42" not in text:
        problems.append(f"tool round trip ended with {text[:60]!r}")
    return problems


def main(argv):
    wanted = []
    for a in argv:
        pid, _, model = a.partition(":")
        if pid not in PROVIDERS:
            print(f"unknown provider {pid!r}. Known: {', '.join(PROVIDERS)}")
            return 2
        wanted.append((pid, model or None))
    if not wanted:
        for pid, p in PROVIDERS.items():
            if p["key_env"] and os.environ.get(p["key_env"]) and pid != "custom":
                wanted.append((pid, None))
        wanted.sort(key=lambda w: w[0] != DEFAULT_FIRST)
    if not wanted:
        print("No API keys found. Set one (for example OPENAI_API_KEY) or name a local provider such as ollama.")
        return 2
    failures = 0
    for pid, model in wanted:
        label = f"{PROVIDERS[pid]['label']} / {model or PROVIDERS[pid]['model']}"
        try:
            problems = test(pid, model)
        except Exception as e:  # network, auth, wrong model name, missing package
            problems = [f"{type(e).__name__}: {str(e)[:160]}"]
        if problems:
            failures += 1
            print(f"FAIL  {label}\n      " + "\n      ".join(problems))
        else:
            print(f"PASS  {label}")
    print(f"\n{len(wanted) - failures}/{len(wanted)} providers passed")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
